-- Civweave hosted AI wallet ledger v1. Idempotent; apply to an isolated branch first.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS civweave_ai_wallet;
CREATE TABLE IF NOT EXISTS civweave_ai_wallet.wallets(wallet_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id text NOT NULL UNIQUE,plan_id text NOT NULL DEFAULT 'local',balance_cents bigint NOT NULL DEFAULT 0,reserved_cents bigint NOT NULL DEFAULT 0,debt_cents bigint NOT NULL DEFAULT 0,daily_spent_cents bigint NOT NULL DEFAULT 0,daily_window date NOT NULL DEFAULT CURRENT_DATE,wallet_version uuid NOT NULL DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT wallets_nonnegative CHECK(balance_cents>=0 AND reserved_cents>=0 AND debt_cents>=0 AND daily_spent_cents>=0),CONSTRAINT wallets_reserve_within_balance CHECK(reserved_cents<=balance_cents));
CREATE TABLE IF NOT EXISTS civweave_ai_wallet.devices(device_id text PRIMARY KEY,user_id text NOT NULL REFERENCES civweave_ai_wallet.wallets(user_id) ON DELETE CASCADE,public_key text,label text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE INDEX IF NOT EXISTS devices_user_active_idx ON civweave_ai_wallet.devices(user_id,revoked_at);
CREATE TABLE IF NOT EXISTS civweave_ai_wallet.payment_events(source_id text PRIMARY KEY,user_id text NOT NULL REFERENCES civweave_ai_wallet.wallets(user_id) ON DELETE RESTRICT,event_type text NOT NULL,amount_cents bigint NOT NULL CHECK(amount_cents>0),payload_hash text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,processed_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS payment_events_user_time_idx ON civweave_ai_wallet.payment_events(user_id,processed_at DESC);
CREATE TABLE IF NOT EXISTS civweave_ai_wallet.reservations(reservation_id text PRIMARY KEY,user_id text NOT NULL REFERENCES civweave_ai_wallet.wallets(user_id) ON DELETE RESTRICT,model text NOT NULL,max_cost_cents bigint NOT NULL CHECK(max_cost_cents>0),actual_cost_cents bigint CHECK(actual_cost_cents>=0 AND actual_cost_cents<=max_cost_cents),status text NOT NULL DEFAULT 'active' CHECK(status IN('active','settled','canceled','expired')),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,settled_at timestamptz,canceled_at timestamptz);
CREATE INDEX IF NOT EXISTS reservations_user_status_idx ON civweave_ai_wallet.reservations(user_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS reservations_expiry_idx ON civweave_ai_wallet.reservations(expires_at) WHERE status='active';
CREATE TABLE IF NOT EXISTS civweave_ai_wallet.ledger_entries(entry_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id text NOT NULL REFERENCES civweave_ai_wallet.wallets(user_id) ON DELETE RESTRICT,entry_type text NOT NULL CHECK(entry_type IN('credit','debit','reservation','settlement','reservation_cancel','reservation_expire','adjustment')),delta_balance_cents bigint NOT NULL DEFAULT 0,delta_reserved_cents bigint NOT NULL DEFAULT 0,delta_debt_cents bigint NOT NULL DEFAULT 0,source_id text,reservation_id text,request_id text,wallet_version uuid NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ledger_user_time_idx ON civweave_ai_wallet.ledger_entries(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS ledger_reservation_idx ON civweave_ai_wallet.ledger_entries(reservation_id) WHERE reservation_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS ledger_source_idx ON civweave_ai_wallet.ledger_entries(source_id) WHERE source_id IS NOT NULL;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.reject_immutable_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION '% is append-only',TG_TABLE_NAME USING ERRCODE='55000'; END;$$;
DROP TRIGGER IF EXISTS ledger_entries_append_only ON civweave_ai_wallet.ledger_entries;
CREATE TRIGGER ledger_entries_append_only BEFORE UPDATE OR DELETE ON civweave_ai_wallet.ledger_entries FOR EACH ROW EXECUTE FUNCTION civweave_ai_wallet.reject_immutable_mutation();
DROP TRIGGER IF EXISTS payment_events_append_only ON civweave_ai_wallet.payment_events;
CREATE TRIGGER payment_events_append_only BEFORE UPDATE OR DELETE ON civweave_ai_wallet.payment_events FOR EACH ROW EXECUTE FUNCTION civweave_ai_wallet.reject_immutable_mutation();
CREATE OR REPLACE FUNCTION civweave_ai_wallet.wallet_snapshot(p_user_id text) RETURNS jsonb LANGUAGE sql STABLE SET search_path=civweave_ai_wallet,public AS $$SELECT jsonb_build_object('schema','civweave.ai-wallet.v1','walletId',w.wallet_id::text,'userId',w.user_id,'planId',w.plan_id,'balanceCents',w.balance_cents,'reservedCents',w.reserved_cents,'debtCents',w.debt_cents,'dailySpentCents',w.daily_spent_cents,'dailyWindow',w.daily_window::text,'walletVersion',w.wallet_version::text,'reservations',COALESCE((SELECT jsonb_object_agg(r.reservation_id,jsonb_build_object('reservationId',r.reservation_id,'maxCostCents',r.max_cost_cents,'model',r.model,'metadata',r.metadata,'createdAt',r.created_at,'expiresAt',r.expires_at)) FROM reservations r WHERE r.user_id=w.user_id AND r.status='active'),'{}'::jsonb),'updatedAt',w.updated_at) FROM wallets w WHERE w.user_id=p_user_id;$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.ensure_wallet(p_user_id text,p_plan_id text DEFAULT 'local') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=civweave_ai_wallet,public AS $$BEGIN IF btrim(COALESCE(p_user_id,''))='' THEN RAISE EXCEPTION 'userId is required'; END IF; IF btrim(COALESCE(p_plan_id,''))='' THEN RAISE EXCEPTION 'planId is required'; END IF; INSERT INTO wallets(user_id,plan_id) VALUES(p_user_id,p_plan_id) ON CONFLICT(user_id) DO NOTHING; RETURN wallet_snapshot(p_user_id); END;$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.register_device(p_user_id text,p_device_id text,p_public_key text DEFAULT NULL,p_label text DEFAULT NULL,p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=civweave_ai_wallet,public AS $$DECLARE v_owner text; BEGIN PERFORM ensure_wallet(p_user_id,'local'); SELECT user_id INTO v_owner FROM devices WHERE device_id=p_device_id; IF FOUND AND v_owner<>p_user_id THEN RAISE EXCEPTION 'Device is already bound to a different user'; END IF; INSERT INTO devices(device_id,user_id,public_key,label,metadata,last_seen_at,revoked_at) VALUES(p_device_id,p_user_id,p_public_key,p_label,COALESCE(p_metadata,'{}'::jsonb),now(),NULL) ON CONFLICT(device_id) DO UPDATE SET public_key=COALESCE(EXCLUDED.public_key,devices.public_key),label=COALESCE(EXCLUDED.label,devices.label),metadata=devices.metadata||EXCLUDED.metadata,last_seen_at=now(),revoked_at=NULL; RETURN true; END;$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.revoke_device(p_user_id text,p_device_id text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=civweave_ai_wallet,public AS $$BEGIN UPDATE devices SET revoked_at=now() WHERE user_id=p_user_id AND device_id=p_device_id AND revoked_at IS NULL; RETURN FOUND; END;$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.device_is_active(p_user_id text,p_device_id text) RETURNS boolean LANGUAGE sql STABLE SET search_path=civweave_ai_wallet,public AS $$SELECT EXISTS(SELECT 1 FROM devices WHERE user_id=p_user_id AND device_id=p_device_id AND revoked_at IS NULL);$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.credit_wallet(p_user_id text,p_amount_cents bigint,p_source_id text,p_plan_id text DEFAULT NULL,p_event_type text DEFAULT 'credit',p_payload_hash text DEFAULT NULL,p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=civweave_ai_wallet,public AS $$DECLARE v_inserted text;v_existing_user text;v_debt bigint;v_applied bigint;v_credited bigint;v_version uuid; BEGIN IF p_amount_cents<1 THEN RAISE EXCEPTION 'amountCents must be positive'; END IF; PERFORM ensure_wallet(p_user_id,COALESCE(p_plan_id,'local')); INSERT INTO payment_events(source_id,user_id,event_type,amount_cents,payload_hash,metadata) VALUES(p_source_id,p_user_id,p_event_type,p_amount_cents,p_payload_hash,COALESCE(p_metadata,'{}'::jsonb)) ON CONFLICT DO NOTHING RETURNING source_id INTO v_inserted; IF v_inserted IS NULL THEN SELECT user_id INTO v_existing_user FROM payment_events WHERE source_id=p_source_id; IF v_existing_user IS DISTINCT FROM p_user_id THEN RAISE EXCEPTION 'Payment source ID is already bound to a different user'; END IF; RETURN wallet_snapshot(p_user_id); END IF; SELECT debt_cents INTO v_debt FROM wallets WHERE user_id=p_user_id FOR UPDATE; v_applied:=LEAST(v_debt,p_amount_cents);v_credited:=p_amount_cents-v_applied;v_version:=gen_random_uuid(); UPDATE wallets SET plan_id=COALESCE(p_plan_id,plan_id),debt_cents=debt_cents-v_applied,balance_cents=balance_cents+v_credited,wallet_version=v_version,updated_at=now() WHERE user_id=p_user_id; INSERT INTO ledger_entries(user_id,entry_type,delta_balance_cents,delta_debt_cents,source_id,wallet_version,metadata) VALUES(p_user_id,'credit',v_credited,-v_applied,p_source_id,v_version,COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('grossCreditCents',p_amount_cents,'appliedToDebtCents',v_applied)); RETURN wallet_snapshot(p_user_id); END;$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.debit_wallet(p_user_id text,p_amount_cents bigint,p_source_id text,p_plan_id text DEFAULT NULL,p_event_type text DEFAULT 'debit',p_payload_hash text DEFAULT NULL,p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=civweave_ai_wallet,public AS $$DECLARE v_inserted text;v_existing_user text;v_available bigint;v_recovered bigint;v_debt_added bigint;v_version uuid; BEGIN IF p_amount_cents<1 THEN RAISE EXCEPTION 'amountCents must be positive'; END IF; INSERT INTO payment_events(source_id,user_id,event_type,amount_cents,payload_hash,metadata) VALUES(p_source_id,p_user_id,p_event_type,p_amount_cents,p_payload_hash,COALESCE(p_metadata,'{}'::jsonb)) ON CONFLICT DO NOTHING RETURNING source_id INTO v_inserted; IF v_inserted IS NULL THEN SELECT user_id INTO v_existing_user FROM payment_events WHERE source_id=p_source_id; IF v_existing_user IS DISTINCT FROM p_user_id THEN RAISE EXCEPTION 'Payment source ID is already bound to a different user'; END IF; RETURN wallet_snapshot(p_user_id); END IF; SELECT balance_cents-reserved_cents INTO v_available FROM wallets WHERE user_id=p_user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No hosted-AI wallet exists for %',p_user_id; END IF; v_recovered:=LEAST(v_available,p_amount_cents);v_debt_added:=p_amount_cents-v_recovered;v_version:=gen_random_uuid(); UPDATE wallets SET plan_id=COALESCE(p_plan_id,plan_id),balance_cents=balance_cents-v_recovered,debt_cents=debt_cents+v_debt_added,wallet_version=v_version,updated_at=now() WHERE user_id=p_user_id; INSERT INTO ledger_entries(user_id,entry_type,delta_balance_cents,delta_debt_cents,source_id,wallet_version,metadata) VALUES(p_user_id,'debit',-v_recovered,v_debt_added,p_source_id,v_version,COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('grossDebitCents',p_amount_cents,'recoveredCents',v_recovered,'debtAddedCents',v_debt_added)); RETURN wallet_snapshot(p_user_id); END;$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.expire_reservations(p_user_id text,p_at timestamptz DEFAULT now()) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=civweave_ai_wallet,public AS $$DECLARE v_row record;v_released bigint:=0;v_version uuid; BEGIN PERFORM 1 FROM wallets WHERE user_id=p_user_id FOR UPDATE; IF NOT FOUND THEN RETURN NULL; END IF; FOR v_row IN SELECT reservation_id,max_cost_cents FROM reservations WHERE user_id=p_user_id AND status='active' AND expires_at<=p_at FOR UPDATE LOOP UPDATE reservations SET status='expired',canceled_at=p_at WHERE reservation_id=v_row.reservation_id;v_released:=v_released+v_row.max_cost_cents;v_version:=gen_random_uuid(); INSERT INTO ledger_entries(user_id,entry_type,delta_reserved_cents,reservation_id,wallet_version,metadata) VALUES(p_user_id,'reservation_expire',-v_row.max_cost_cents,v_row.reservation_id,v_version,jsonb_build_object('expiredAt',p_at)); END LOOP; IF v_released>0 THEN UPDATE wallets SET reserved_cents=GREATEST(0,reserved_cents-v_released),wallet_version=COALESCE(v_version,gen_random_uuid()),updated_at=p_at WHERE user_id=p_user_id; END IF; RETURN wallet_snapshot(p_user_id); END;$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.reserve_wallet(p_user_id text,p_reservation_id text,p_max_cost_cents bigint,p_model text,p_metadata jsonb DEFAULT '{}'::jsonb,p_ttl_seconds integer DEFAULT 900,p_max_request_cents bigint DEFAULT 1,p_daily_limit_cents bigint DEFAULT 1) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=civweave_ai_wallet,public AS $$DECLARE v_wallet wallets%ROWTYPE;v_existing reservations%ROWTYPE;v_version uuid; BEGIN IF p_ttl_seconds<30 OR p_ttl_seconds>900 THEN RAISE EXCEPTION 'Reservation lifetime must be between 30 and 900 seconds'; END IF; IF p_max_cost_cents<1 OR p_max_cost_cents>p_max_request_cents THEN RAISE EXCEPTION 'Request reservation exceeds the plan per-request limit'; END IF; PERFORM expire_reservations(p_user_id,now()); SELECT * INTO v_wallet FROM wallets WHERE user_id=p_user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No hosted-AI wallet exists for %',p_user_id; END IF; IF v_wallet.debt_cents>0 THEN RAISE EXCEPTION 'Hosted-AI wallet has an unpaid refund or chargeback balance'; END IF; IF v_wallet.daily_window<>CURRENT_DATE THEN UPDATE wallets SET daily_window=CURRENT_DATE,daily_spent_cents=0,updated_at=now() WHERE user_id=p_user_id RETURNING * INTO v_wallet; END IF; SELECT * INTO v_existing FROM reservations WHERE reservation_id=p_reservation_id; IF FOUND THEN IF v_existing.user_id=p_user_id AND v_existing.model=p_model AND v_existing.max_cost_cents=p_max_cost_cents AND v_existing.status='active' THEN RETURN wallet_snapshot(p_user_id); END IF; RAISE EXCEPTION 'Reservation ID is already bound to different request details'; END IF; IF v_wallet.daily_spent_cents+v_wallet.reserved_cents+p_max_cost_cents>p_daily_limit_cents THEN RAISE EXCEPTION 'Request reservation exceeds the plan daily hosted-AI limit'; END IF; IF v_wallet.balance_cents-v_wallet.reserved_cents<p_max_cost_cents THEN RAISE EXCEPTION 'Insufficient hosted-AI balance'; END IF; v_version:=gen_random_uuid(); INSERT INTO reservations(reservation_id,user_id,model,max_cost_cents,metadata,expires_at) VALUES(p_reservation_id,p_user_id,p_model,p_max_cost_cents,COALESCE(p_metadata,'{}'::jsonb),now()+make_interval(secs=>p_ttl_seconds)); UPDATE wallets SET reserved_cents=reserved_cents+p_max_cost_cents,wallet_version=v_version,updated_at=now() WHERE user_id=p_user_id; INSERT INTO ledger_entries(user_id,entry_type,delta_reserved_cents,reservation_id,wallet_version,metadata) VALUES(p_user_id,'reservation',p_max_cost_cents,p_reservation_id,v_version,COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('model',p_model)); RETURN wallet_snapshot(p_user_id); END;$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.settle_wallet(p_user_id text,p_reservation_id text,p_actual_cost_cents bigint,p_request_id text DEFAULT NULL,p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=civweave_ai_wallet,public AS $$DECLARE v_wallet wallets%ROWTYPE;v_res reservations%ROWTYPE;v_version uuid; BEGIN SELECT * INTO v_wallet FROM wallets WHERE user_id=p_user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No hosted-AI wallet exists for %',p_user_id; END IF; SELECT * INTO v_res FROM reservations WHERE reservation_id=p_reservation_id FOR UPDATE; IF NOT FOUND OR v_res.user_id<>p_user_id THEN RAISE EXCEPTION 'Unknown reservation: %',p_reservation_id; END IF; IF v_res.status='settled' THEN IF v_res.actual_cost_cents=p_actual_cost_cents THEN RETURN wallet_snapshot(p_user_id); END IF; RAISE EXCEPTION 'Reservation is already settled with a different amount'; END IF; IF v_res.status<>'active' THEN RAISE EXCEPTION 'Reservation is not active'; END IF; IF p_actual_cost_cents<0 OR p_actual_cost_cents>v_res.max_cost_cents THEN RAISE EXCEPTION 'Actual provider cost cannot exceed the reserved maximum'; END IF; v_version:=gen_random_uuid(); UPDATE reservations SET status='settled',actual_cost_cents=p_actual_cost_cents,settled_at=now() WHERE reservation_id=p_reservation_id; UPDATE wallets SET balance_cents=balance_cents-p_actual_cost_cents,reserved_cents=reserved_cents-v_res.max_cost_cents,daily_spent_cents=(CASE WHEN daily_window=CURRENT_DATE THEN daily_spent_cents ELSE 0 END)+p_actual_cost_cents,daily_window=CURRENT_DATE,wallet_version=v_version,updated_at=now() WHERE user_id=p_user_id; INSERT INTO ledger_entries(user_id,entry_type,delta_balance_cents,delta_reserved_cents,reservation_id,request_id,wallet_version,metadata) VALUES(p_user_id,'settlement',-p_actual_cost_cents,-v_res.max_cost_cents,p_reservation_id,p_request_id,v_version,COALESCE(p_metadata,'{}'::jsonb)||jsonb_build_object('releasedCents',v_res.max_cost_cents-p_actual_cost_cents,'model',v_res.model)); RETURN wallet_snapshot(p_user_id); END;$$;
CREATE OR REPLACE FUNCTION civweave_ai_wallet.cancel_wallet(p_user_id text,p_reservation_id text,p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=civweave_ai_wallet,public AS $$DECLARE v_res reservations%ROWTYPE;v_version uuid; BEGIN PERFORM 1 FROM wallets WHERE user_id=p_user_id FOR UPDATE; IF NOT FOUND THEN RETURN NULL; END IF; SELECT * INTO v_res FROM reservations WHERE reservation_id=p_reservation_id FOR UPDATE; IF NOT FOUND OR v_res.user_id<>p_user_id THEN RETURN wallet_snapshot(p_user_id); END IF; IF v_res.status IN('canceled','expired') THEN RETURN wallet_snapshot(p_user_id); END IF; IF v_res.status='settled' THEN RAISE EXCEPTION 'Settled reservations cannot be canceled'; END IF; v_version:=gen_random_uuid(); UPDATE reservations SET status='canceled',canceled_at=now() WHERE reservation_id=p_reservation_id; UPDATE wallets SET reserved_cents=reserved_cents-v_res.max_cost_cents,wallet_version=v_version,updated_at=now() WHERE user_id=p_user_id; INSERT INTO ledger_entries(user_id,entry_type,delta_reserved_cents,reservation_id,wallet_version,metadata) VALUES(p_user_id,'reservation_cancel',-v_res.max_cost_cents,p_reservation_id,v_version,COALESCE(p_metadata,'{}'::jsonb)); RETURN wallet_snapshot(p_user_id); END;$$;
REVOKE ALL ON SCHEMA civweave_ai_wallet FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA civweave_ai_wallet FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA civweave_ai_wallet FROM PUBLIC;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA civweave_ai_wallet FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA civweave_ai_wallet REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA civweave_ai_wallet REVOKE ALL ON SEQUENCES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA civweave_ai_wallet REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
